using System.Collections.Generic;
using Forgebound.Core.Progression;
using UnityEngine;

namespace Forgebound.Presentation
{
    /// <summary>
    /// Pooled SFX with per-clip rate limiting (prevents ear fatigue from 50 procs/second), a global voice cap,
    /// music cross-fade per biome and ducking under important stingers. Clips: Resources/Audio/&lt;id&gt; (generated by
    /// tools/audio/synth.py — original, provenance in Resources/Audio/audio_manifest.json). Missing clips are silent
    /// and logged once.
    /// </summary>
    public sealed class AudioManager : MonoBehaviour
    {
        public const int MaxVoices = 16;
        public const float MinInterval = 0.05f;   // same clip at most every 50 ms
        public const int MaxSameClip = 3;

        private readonly List<AudioSource> _voices = new List<AudioSource>();
        private readonly Dictionary<string, AudioClip> _clips = new Dictionary<string, AudioClip>();
        private readonly Dictionary<string, float> _lastPlayed = new Dictionary<string, float>();
        private readonly HashSet<string> _missing = new HashSet<string>();
        private AudioSource _musicA, _musicB;
        private bool _musicOnA = true;
        private float _master = 0.8f, _music = 0.7f, _sfx = 0.8f;
        private float _duck = 1f, _duckUntil;
        private string _musicId;
        public int PlayedThisSecond, SuppressedThisSecond;
        private float _secondStart;

        public void Init(Services s)
        {
            for (int i = 0; i < MaxVoices; i++)
            {
                var src = gameObject.AddComponent<AudioSource>();
                src.playOnAwake = false;
                _voices.Add(src);
            }
            _musicA = gameObject.AddComponent<AudioSource>();
            _musicB = gameObject.AddComponent<AudioSource>();
            _musicA.loop = _musicB.loop = true;
            _musicA.playOnAwake = _musicB.playOnAwake = false;
        }

        public void ApplyVolumes(Settings s)
        {
            _master = s.MasterVolume / 100f;
            _music = s.MusicVolume / 100f;
            _sfx = s.SfxVolume / 100f;
        }

        private AudioClip Clip(string id)
        {
            if (string.IsNullOrEmpty(id)) return null;
            AudioClip c;
            if (_clips.TryGetValue(id, out c)) return c;
            c = Resources.Load<AudioClip>("Audio/" + id);
            _clips[id] = c;
            if (c == null && _missing.Add(id)) Debug.Log("[Forgebound] audio clip missing: " + id);
            return c;
        }

        public void Ui(string id) { Play(id, 0.8f, 1f); }

        /// <summary>Play a one-shot with rate limiting. Pitch jitter keeps repeated hits from sounding mechanical.</summary>
        public void Play(string id, float volume = 1f, float pitch = 1f, float priority = 0.5f)
        {
            float now = Time.unscaledTime;
            if (now - _secondStart > 1f) { _secondStart = now; PlayedThisSecond = 0; SuppressedThisSecond = 0; }
            float last;
            if (_lastPlayed.TryGetValue(id ?? "", out last) && now - last < MinInterval) { SuppressedThisSecond++; return; }
            var clip = Clip(id);
            if (clip == null) return;
            int same = 0;
            AudioSource free = null;
            foreach (var v in _voices)
            {
                if (v.isPlaying && v.clip == clip) same++;
                if (!v.isPlaying && free == null) free = v;
            }
            if (same >= MaxSameClip) { SuppressedThisSecond++; return; }
            if (free == null)
            {
                if (priority < 0.7f) { SuppressedThisSecond++; return; }
                free = _voices[0];
                foreach (var v in _voices) if (v.time > free.time) free = v;   // steal the oldest voice
            }
            free.clip = clip;
            free.volume = Mathf.Clamp01(volume * _sfx * _master);
            free.pitch = pitch * Random.Range(0.96f, 1.04f);
            free.Play();
            _lastPlayed[id] = now;
            PlayedThisSecond++;
        }

        /// <summary>Important stinger (boss phase, legendary forge): ducks music for a moment.</summary>
        public void Stinger(string id)
        {
            Play(id, 1f, 1f, 1f);
            _duck = 0.35f;
            _duckUntil = Time.unscaledTime + 1.2f;
        }

        public void Music(string id)
        {
            if (id == _musicId) return;
            _musicId = id;
            var clip = Clip(id);
            var next = _musicOnA ? _musicB : _musicA;
            _musicOnA = !_musicOnA;
            next.clip = clip;
            next.volume = 0;
            if (clip != null) next.Play();
        }

        private void Update()
        {
            if (Time.unscaledTime > _duckUntil) _duck = Mathf.MoveTowards(_duck, 1f, Time.unscaledDeltaTime);
            var active = _musicOnA ? _musicA : _musicB;
            var other = _musicOnA ? _musicB : _musicA;
            float target = 0.5f * _music * _master * _duck;
            active.volume = Mathf.MoveTowards(active.volume, active.clip != null ? target : 0, Time.unscaledDeltaTime * 0.5f);
            other.volume = Mathf.MoveTowards(other.volume, 0, Time.unscaledDeltaTime * 0.5f);
            if (other.volume <= 0 && other.isPlaying) other.Stop();
        }
    }
}
